            partials[(m * S + s) * 2 + 1] = s2;
            __threadfence();
            unsigned int old = atomicAdd(barCount, 1u);
            if (old == gridDim.x - 1) {
                *barCount = 0u;
                __threadfence();
                atomicExch(barCount + 1, 1u);
            }
        }
    }
    if (tid == 0) {
        volatile unsigned int* flag = barCount + 1;
        while (*flag == 0u) { __nanosleep(32); }
    }
    __syncthreads();
    __shared__ float smean, srstd;
    if (wid == 0) {
        const float* pr = partials + m * S * 2;
        float t1 = 0.f, t2 = 0.f;
        for (int i = lane; i < S; i += 32) {
            t1 += pr[i * 2];
            t2 += pr[i * 2 + 1];
        }
        for (int off = 16; off > 0; off >>= 1) {
            t1 += __shfl_down_sync(FULL_MASK, t1, off);
            t2 += __shfl_down_sync(FULL_MASK, t2, off);
        }
        if (lane == 0) {
            float mean = t1 / N;
            float var = t2 / N - mean * mean;
            var = var < 0.f ? 0.f : var;
            smean = mean;
            srstd = rsqrtf(var + eps);
        }
    }
    __syncthreads();
    float mean = smean, rstd = srstd;
    const float4* wr = w + s * n4;
    const float4* br = b + s * n4;
    float4* op = out + (long)m * (N / 4) + s * n4;
    for (int i = tid; i < n4; i += nthreads) {
        float4 v = sm[i];
        float4 wv = wr[i];
        float4 bv = br[i];
        float4 o;
        o.x = (v.x - mean) * rstd * wv.x + bv.x;
        o.y = (v.y - mean) * rstd * wv.y + bv.y;
        o.z = (v.z - mean) * rstd * wv.z + bv.z;
        o.w = (v.w - mean) * rstd * wv.w + bv.w;
        op[i] = o;
    }
}

int64_t smem_max_blocks(int64_t threads, int64_t smem) {
    cudaFuncSetAttribute(ln_smem_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
    int numBlocksPerSm = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&numBlocksPerSm, ln_smem_kernel, (int)threads, (int)smem);
    int smcount = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
    return (int64_t)numBlocksPerSm * smcount;
}

void ln_smem(torch::Tensor x, torch::Tensor w, torch::Tensor b, torch::Tensor out,
             torch::Tensor partials, torch::Tensor bar, int64_t S, int64_t threads, double eps) {
    int N = (int)w.numel();
    long M = x.numel() / N;
    dim3 grid((unsigned)(M * S));
    int smem = (int)(N / S) * 4;
    cudaFuncSetAttribute(ln_smem_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, smem);
    auto stream = at::cuda::getCurrentCUDAStream();
    ln_smem_kernel<<<grid, (int)threads, smem, stream>>>(
        reinterpret_cast<const float4*>(x.data_ptr<float>()),
        reinterpret_cast<const float4*>(w.data_ptr<float>()),
        reinterpret_cast<const float4*>(b.data_ptr<float>()),
        reinterpret_cast<float4*>(out.data_ptr<float>()),
        partials.data_ptr<float>(),
        reinterpret_cast<unsigned int*>(bar.data_ptr<int>()),
        N, (int)S, (float)eps);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("ln_smem", &ln_smem, "smem fused");
    m.def("smem_max_blocks", &smem_max_blocks, "occupancy");
}
